import os,re
def imps(m):
    p=m.replace('.','/')+'.lean'
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)',open(p).read(),re.M) if os.path.exists(p) else []
seen,st=set(),['AlgebraicJacobian']
while st:
    m=st.pop()
    if m not in seen: seen.add(m); st+=imps(m)
allm={os.path.join(d,f)[:-5].replace('/','.') for d,_,fs in os.walk('AlgebraicJacobian') for f in fs if f.endswith('.lean')}
print('on disk',len(allm),'rooted',len(allm&seen))
print('unrooted:',sorted(allm-seen) or 'none')
