import json
d=json.load(open('/tmp/roadmap.json'))
items=d['items']
print('items',len(items)); print('keys',list(items[0].keys()))
byid={i['id']:i for i in items}
kids={}
for i in items:
    p=i.get('parent')
    if p: kids.setdefault(p,[]).append(i['id'])
OPEN={'pending','active','blocked','in_progress','todo'}
for i in items:
    if not i['id'].startswith('AJC'): continue
    ch=kids.get(i['id'],[])
    if not ch: continue
    st=[byid[c]['status'] for c in ch]
    alldone=all(s in ('done','dropped','cancelled') for s in st)
    if alldone and i['status'] not in ('done','dropped','cancelled'):
        print('MISMATCH(A) parent %s [%s] all children done: %s'%(i['id'],i['status'],[(c,byid[c]['status']) for c in ch]))
    if i['status']=='done' and any(s not in ('done','dropped','cancelled') for s in st):
        print('MISMATCH(B) parent %s [done] open children: %s'%(i['id'],[(c,byid[c]['status']) for c in ch if byid[c]['status'] not in ('done','dropped','cancelled')]))
EOF

